# Restore and replay exact locally tested original Adventurer's Inn V1.
import base64,gzip,hashlib,runpy
from pathlib import Path
here=Path(__file__).resolve().parent
source=gzip.decompress(base64.b64decode("""""",validate=True))
assert hashlib.sha256(source).hexdigest()=="3135f85d5f29b9d6f9ac9998a0d8c2fc605b60f46faa3dafdbc01e3b7942f100"
script=here/"build_inn.py"
if script.exists() and script.read_bytes()!=source: raise RuntimeError("Preserve manually edited source before replay")
script.write_bytes(source)
runpy.run_path(str(script),run_name="__main__")
assert hashlib.sha256(gzip.decompress((here/"prefab-extension/adventurers_inn.nbt").read_bytes())).hexdigest()=="c13847924de17b043f32f15c75792738a654d122f42be45ec15191cb9feeb902"
